package fr.roadguard.app;

import android.app.*;import android.content.*;import android.media.audiofx.*;import android.os.*;import android.widget.*;import java.util.*;

/** Optional real effects on announced nonzero sessions. No global/session-zero processing. */
final class MobileAudioStudio {
  private static final LinkedHashMap<Integer,Equalizer> sessions=new LinkedHashMap<>();
  private static final Map<Integer,BassBoost> bass=new HashMap<>();private static Context app;
  private static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("roadguard_equalizer",0);}
  private static final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){int id=i.getIntExtra(AudioEffect.EXTRA_AUDIO_SESSION,-1);if(id<=0)return;if(AudioEffect.ACTION_CLOSE_AUDIO_EFFECT_CONTROL_SESSION.equals(i.getAction()))release(id);else attach(c,id);}};
  static synchronized void start(Context context){if(app!=null)return;Context c=context.getApplicationContext();IntentFilter f=new IntentFilter(AudioEffect.ACTION_OPEN_AUDIO_EFFECT_CONTROL_SESSION);f.addAction(AudioEffect.ACTION_CLOSE_AUDIO_EFFECT_CONTROL_SESSION);try{if(Build.VERSION.SDK_INT>=33)c.registerReceiver(receiver,f,Context.RECEIVER_EXPORTED);else c.registerReceiver(receiver,f);app=c;}catch(RuntimeException unavailable){}}
  private static synchronized void release(int id){Equalizer e=sessions.remove(id);BassBoost b=bass.remove(id);try{if(e!=null)e.release();}catch(RuntimeException ignored){}try{if(b!=null)b.release();}catch(RuntimeException ignored){}}
  private static synchronized void attach(Context c,int id){if(sessions.containsKey(id))return;Equalizer eq=null;try{eq=new Equalizer(0,id);if(!eq.hasControl()){eq.release();return;}if(sessions.size()>=8)release(sessions.keySet().iterator().next());sessions.put(id,eq);try{bass.put(id,new BassBoost(0,id));}catch(RuntimeException unavailable){}eq.setControlStatusListener((effect,granted)->{if(granted)apply(c);});apply(c);}catch(RuntimeException unavailable){if(sessions.containsKey(id))release(id);else if(eq!=null)try{eq.release();}catch(RuntimeException ignored){}}}
  private static synchronized void apply(Context c){android.content.SharedPreferences p=prefs(c);int[] curve=new int[10];for(int i=0;i<10;i++)curve[i]=p.getInt("gain_"+i,0);boolean enabled=p.getBoolean("enabled",false),headroom=p.getBoolean("headroom",true);
    for(Map.Entry<Integer,Equalizer> entry:sessions.entrySet())try{Equalizer eq=entry.getValue();if(!eq.hasControl())continue;short[] range=eq.getBandLevelRange();int bands=Math.min(32,eq.getNumberOfBands());for(short b=0;b<bands;b++)eq.setBandLevel(b,(short)AudioCurve.gain(curve,eq.getCenterFreq(b)/1000d,headroom,range[0],range[1]));eq.setEnabled(enabled);BassBoost boost=bass.get(entry.getKey());if(boost!=null&&boost.hasControl()){int value=Math.max(0,Math.min(1000,p.getInt("bass",0)));if(boost.getStrengthSupported())boost.setStrength((short)value);boost.setEnabled(enabled&&value>0);}}catch(RuntimeException unavailable){}
  }
  private static synchronized String status(){StringBuilder s=new StringBuilder();for(Equalizer eq:sessions.values())try{if(eq.hasControl()&&eq.getEnabled()){if(s.length()>0)s.append(", ");s.append(eq.getNumberOfBands()).append(" bandes matérielles");}}catch(RuntimeException unavailable){}return s.length()>0?"Traitement actif · "+s:"Aucune session compatible traitée. Active le Studio puis relance une lecture dans un lecteur compatible. Certaines applications utilisent leur propre égaliseur.";}
  static void close(MainActivity a){AlertDialog d=a.audioStudioDialog;a.audioStudioDialog=null;if(d!=null)d.dismiss();}
  static void show(Activity a){if(a.isFinishing()||a.isDestroyed())return;if(a instanceof MainActivity&&((MainActivity)a).audioStudioDialog!=null&&((MainActivity)a).audioStudioDialog.isShowing())return;start(a);android.content.SharedPreferences p=prefs(a);LinearLayout box=new LinearLayout(a);box.setOrientation(1);int pad=(int)(18*a.getResources().getDisplayMetrics().density);box.setPadding(pad,pad,pad,pad);TextView state=new TextView(a);box.addView(state);
    Switch enabled=new Switch(a);enabled.setText("Activer le traitement audio");enabled.setChecked(p.getBoolean("enabled",false));box.addView(enabled);enabled.setOnCheckedChangeListener((b,v)->{p.edit().putBoolean("enabled",v).apply();apply(a);state.setText(status());});
    Switch reserve=new Switch(a);reserve.setText("Réserve de niveau · limiter les crêtes amplifiées");reserve.setChecked(p.getBoolean("headroom",true));box.addView(reserve);reserve.setOnCheckedChangeListener((b,v)->{p.edit().putBoolean("headroom",v).apply();apply(a);});
    Spinner presets=new Spinner(a);presets.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AudioCurve.PRESETS));box.addView(presets);SeekBar[] sliders=new SeekBar[10];
    for(int i=0;i<10;i++){final int band=i;TextView label=new TextView(a);box.addView(label);SeekBar slider=new SeekBar(a);sliders[i]=slider;slider.setMax(2400);slider.setProgress(Math.max(0,Math.min(2400,p.getInt("gain_"+i,0)+1200)));slider.setContentDescription(AudioCurve.HZ[i]+" Hz");box.addView(slider);label.setText(AudioCurve.HZ[i]+" Hz · "+String.format(Locale.getDefault(),"%.1f",(slider.getProgress()-1200)/100f)+" dB");slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int v,boolean user){label.setText(AudioCurve.HZ[band]+" Hz · "+String.format(Locale.getDefault(),"%.1f",(v-1200)/100f)+" dB");p.edit().putInt("gain_"+band,v-1200).apply();apply(a);}});}
    presets.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> x){}public void onItemSelected(AdapterView<?> x,android.view.View v,int index,long id){if(index>0)for(int i=0;i<10;i++)sliders[i].setProgress(AudioCurve.CURVES[index-1][i]+1200);}});
    TextView bassLabel=new TextView(a);bassLabel.setText("Renfort des basses · si pris en charge");box.addView(bassLabel);SeekBar boost=new SeekBar(a);boost.setMax(1000);boost.setProgress(Math.max(0,Math.min(1000,p.getInt("bass",0))));box.addView(boost);boost.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int v,boolean user){p.edit().putInt("bass",v).apply();apply(a);}});
    TextView note=new TextView(a);note.setText("Courbe mémorisée sur ce téléphone. Les dix réglages sont adaptés aux bandes réellement disponibles. Le Studio ne peut pas traiter toutes les applications ; les alertes radar gardent leur priorité audio.");box.addView(note);
    Button system=new Button(a);system.setText("Ouvrir l’égaliseur Android");box.addView(system);system.setOnClickListener(v->{try{int id;synchronized(MobileAudioStudio.class){id=sessions.isEmpty()?-1:sessions.keySet().iterator().next();}Intent intent=new Intent(AudioEffect.ACTION_DISPLAY_AUDIO_EFFECT_CONTROL_PANEL).putExtra(AudioEffect.EXTRA_PACKAGE_NAME,a.getPackageName());if(id>0)intent.putExtra(AudioEffect.EXTRA_AUDIO_SESSION,id);a.startActivity(intent);}catch(RuntimeException unavailable){Toast.makeText(a,"Aucun égaliseur système disponible",Toast.LENGTH_LONG).show();}});
    ScrollView scroll=new ScrollView(a);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Studio audio ROADGUARD").setView(scroll).setPositiveButton("Fermer",null).create();if(a instanceof MainActivity)((MainActivity)a).audioStudioDialog=dialog;Handler h=new Handler(Looper.getMainLooper());Runnable refresh=new Runnable(){public void run(){if(!dialog.isShowing())return;if(a.isDestroyed()||a.isFinishing()){dialog.dismiss();return;}state.setText(status());h.postDelayed(this,1000);}};dialog.setOnDismissListener(d->{h.removeCallbacksAndMessages(null);if(a instanceof MainActivity&&((MainActivity)a).audioStudioDialog==dialog)((MainActivity)a).audioStudioDialog=null;});dialog.show();h.post(refresh);
  }
  private MobileAudioStudio(){}
}
